var attemptPatchColumns = entpatch.Columns{
	1: attempt.FieldId, 2: attempt.TenantColumn, 3: attempt.SiteColumn, 8: attempt.LaminaColumn, 9: attempt.SinkColumn, 10: attempt.NodeColumn, 11: attempt.FieldState, 12: attempt.FieldFailureReason, 13: attempt.FieldDateUpdated, 15: attempt.FieldDateCreated, 16: attempt.FieldDateExpires, 17: attempt.FieldDateFinished, 18: attempt.FieldRank}

func (s AttemptServiceServer) apply(ctx context.Context, ref *api.AttemptRef, doc *patchpb.Patch, by string) (*api.Attempt, error) {
	plan := &ormpatch.Plan{Entity: attemptOrmEntity}
	if doc != nil {
		v, err := ormpatch.Compile(attemptOrmEntity, doc)
		if err != nil {
			if errors.Is(err, ormpatch.ErrUnsupported) {
				return nil, status.Errorf(codes.Unimplemented, "%s", err)
			}
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		plan = v
		for i, u := range plan.Writes {
			switch u.Prop.Number() {
			case 13, 15, 16, 17:
				if op, ok := u.Op.(ormpatch.SetColumn); ok {
					plan.Writes[i].Op = ormpatch.SetColumn{Value: writtenTimestamp(op.Value)}
				}
			}
		}
	}

	pred, mod, err := entpatch.Build(plan, attemptPatchColumns, s.Db.Dialect())
	if err != nil {
		if errors.Is(err, entpatch.ErrValue) {
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		return nil, status.Errorf(codes.Internal, "%s", err)
	}

	tx, err := join(ctx, s.Db, true, s.admission != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	k, err := AttemptGetKey(ctx, st.Db, ref)
	if err != nil {
		return nil, err
	}
	at := &api.AttemptRef{}
	at.SetId(k[:])
	p, err := s.narrow(ctx, attempt.IdEQ(k))
	if err != nil {
		return nil, err
	}

	var previous *api.Attempt
	images := s.images(by)
	if images.Previous && mod != nil {
		u, err := st.snapshot(ctx, p, true)
		if err != nil {
			if ent.IsNotFound(err) {
				return nil, status.Error(codes.NotFound, "resource not found")
			}
			return nil, err
		}
		previous = s.image(u.Proto())
	}
	if mod == nil {
		q := st.Db.Attempt.Query().Where(p)
		if pred != nil {
			q.Where(predicate.Attempt(pred))
		}
		if ok, err := q.Exist(ctx); err != nil {
			return nil, err
		} else if !ok {
			return nil, func() error {
				if ok, err := st.Db.Attempt.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "Attempt not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	} else {
		q := st.Db.Attempt.Update().Where(p)
		if pred != nil {
			q.Where(predicate.Attempt(pred))
		}
		q.Modify(mod)
		if !plan.WritesTo(13) {
			q.SetDateUpdated(st.now())
		}
		tx.Writing()
		if n, err := q.Save(ctx); err != nil {
			if err, ok := err.(*ent.ConstraintError); ok {
				if sqlgraph.IsUniqueConstraintError(err) {
					return nil, status.Error(codes.AlreadyExists, "Attempt already exists")
				}
				if sqlgraph.IsForeignKeyConstraintError(err) {
					return nil, status.Error(codes.NotFound, "Attempt: referenced entity not found")
				}
			}
			return nil, err
		} else if n == 0 {
			return nil, func() error {
				if ok, err := st.Db.Attempt.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "Attempt not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	}

	out, err := st.Get(ctx, at.Pick())
	if err != nil {
		return nil, err
	}
	if mod != nil {
		var value *api.Attempt
		if images.Value {
			value = s.image(out)
		}
		if err := record(ctx, s.Rec, s.admission, st.Db, Change{
			Entity:   "shale.Attempt",
			By:       by,
			Key:      k,
			Patch:    doc,
			Previous: previous, Value: value,
		}); err != nil {
			return nil, err
		}
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return out, nil
}

func (s AttemptServiceServer) Erase(ctx context.Context, req *api.AttemptRef) (*api.AttemptEraseResponse, error) {
	if s.admission != nil {
		ctx = request(ctx, req)
	}
	p, err := AttemptPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := join(ctx, s.Db, s.Rec != nil || s.admission != nil, s.admission != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	var previous *api.Attempt
	if s.Rec != nil || s.admission != nil {
		images := s.images(api.AttemptService_Erase_FullMethodName)
		var v *ent.Attempt
		var err error
		if images.Previous {
			v, err = st.snapshot(ctx, p, true)
		} else {
			v, err = st.Db.Attempt.Query().Where(p).Select(attempt.FieldId).Only(ctx)
		}
		if err != nil {
			if ent.IsNotFound(err) {
				return &api.AttemptEraseResponse{}, nil
			}
			return nil, err
		}

		k = v.Id
		if images.Previous {
			previous = s.image(v.Proto())
		}
		p = attempt.And(p, attempt.IdEQ(v.Id))
	}

	tx.Writing()
	n, err := st.Db.Attempt.Delete().Where(p).Exec(ctx)
	if err != nil {
		if err, ok := err.(*ent.ConstraintError); ok && sqlgraph.IsForeignKeyConstraintError(err) {
			return nil, status.Error(codes.FailedPrecondition, "Attempt is still named by another row and cannot be erased")
		}
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, s.admission, st.Db, Change{
			Entity:   "shale.Attempt",
			By:       api.AttemptService_Erase_FullMethodName,
			Key:      k,
			Previous: previous,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &api.AttemptEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

func AttemptPick(req *api.AttemptRef) (predicate.Attempt, error) {
	switch req.WhichKey() {
	case api.AttemptRef_Id_case:
		if v, err := entuuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return attempt.IdEQ(v), nil
		}
	case api.AttemptRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: Attempt")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}
